    author_id uuid NOT NULL,
    day_type text NOT NULL,
    summary text,
    total_minutes integer NOT NULL,
    status text NOT NULL,
    submitted_at timestamptz,
    idempotency_key text NOT NULL,
    UNIQUE (daily_log_id,revision),
    UNIQUE (idempotency_key),
    UNIQUE (id,daily_log_id),
    CHECK (revision > 0),
    CHECK (total_minutes >= 0)
 );
-- DB-057 Kun ichidagi bajarilgan ishlar
CREATE TABLE log_task_entries (
    id uuid NOT NULL PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    revision_id uuid NOT NULL,
    plan_task_id uuid,
    result_text text NOT NULL,
    minutes integer NOT NULL,
    start_minute integer,
    end_minute integer,
    CHECK (minutes > 0),
    CHECK ((start_minute IS NULL AND end_minute IS NULL) OR (start_minute >= 0 AND end_minute <= 1440 AND end_minute > start_minute AND minutes = end_minute - start_minute))
 );
